import{prepare,ready}from'./browser.js';import{records,fakeMap,services}from'./routing.js';
export const owner='00000000-0000-4000-8000-000000000001',portfolio='00000000-0000-4000-8000-000000000000';
export const appointment=(id,targetId,date,time='09:00',extra={})=>({id,user_id:owner,portfolio_id:portfolio,kind:'schedule',revision:1,deleted:false,updated_at:'2026-10-30T00:00:00Z',data:{title:'Visita '+targetId,targetType:'client',targetId:String(targetId),startDate:date,time,timeZone:'America/Fortaleza',durationMinutes:20,repeat:'once',reminders:[4320,1440,60],...extra}});
export async function setup(page,{rows=[],plan='pro',clock=null}={}){
 if(clock)await page.clock.install({time:new Date(clock)});
 await prepare(page,{records,lockAuthFixture:true});
 await page.addInitScript(({rows,plan,owner,portfolio})=>{if(!localStorage.getItem('__appointment_cloud'))localStorage.setItem('__appointment_cloud',JSON.stringify(rows));const base=window.supabase.createClient;window.supabase.createClient=(...args)=>{const api=base(...args),originalRpc=api.rpc,from=api.from,load=()=>JSON.parse(localStorage.getItem('__appointment_cloud')||'[]');api.rpc=async(name,p)=>{if(name==='traxelo_plan_access')return {data:{plan,beta:true,routeLimit:null,routeCount:0}};if(name!=='traxelo_write_owned_item')return originalRpc(name,p);if(window.__failAppointment)return {error:{message:'Falha de comunicação'}};const all=load(),old=all.find(r=>r.id===p.p_id);if((old?.revision||0)!==p.p_revision)return {error:{code:'40001',message:'Registro alterado'}};const row={id:p.p_id,user_id:p.p_owner,portfolio_id:window.RotaMapaPortfolioScope?.loadedId||portfolio,kind:p.p_kind,data:p.p_data,revision:(old?.revision||0)+1,deleted:p.p_deleted,updated_at:new Date().toISOString()};localStorage.setItem('__appointment_cloud',JSON.stringify([...all.filter(r=>r.id!==row.id),row]));return {data:row};};api.from=table=>{if(table!=='traxelo_workspace_items')return from(table);let filters={},offset=0,end=499;const chain={select:()=>chain,eq:(k,v)=>{filters[k]=v;return chain;},order:()=>chain,range:(a,b)=>{offset=a;end=b;return chain;},then:yes=>Promise.resolve({data:load().filter(r=>Object.entries(filters).every(([k,v])=>r[k]===v)).slice(offset,end+1)}).then(yes)};return chain;};return api;};Object.defineProperty(navigator,'geolocation',{configurable:true,value:{getCurrentPosition:ok=>ok({coords:{latitude:-5.8,longitude:-35.22,accuracy:8},timestamp:Date.now()}),watchPosition:()=>1,clearWatch(){}}});},{rows,plan,owner,portfolio});
 await ready(page);await fakeMap(page);await services(page);await page.locator('#workspacePlanStatus').filter({hasText:plan==='pro'?'Pro':plan==='plus'?'Plus':'Free'}).waitFor({state:'attached'});await page.locator('[data-tab=agendamentos]').click();
}
